import sys

def restore_string(s, t):
    if s == t:
        return 0, []

    j, min_k = 0, sys.maxsize
    res_lines = []

    for i in range(1, len(s)):
        if s[:i] == t[:i] and s[i:] == t[i:]:
            sub_s = s[:i] + s[i+1:]
            sub_t = t[:i] + t[i+1:]

            if sub_s == sub_t:
                for k in find_intersections(sub_s):
                    rest_len = len(sub_s) - sum(k)
                    if rest_len < min_k:
                        min_k = rest_len
                        res_lines = [f"{i} {j}"]
                    elif rest_len == min_k:
                        res_lines.append(f"{i} {j}")
            else:
                break

        j += 1

    return min_k, [f"{i+1} {j+1}" for i, k in enumerate(res_lines) for j in k]

def find_intersections(s):
    intersections = []
    for i in range(2, len(s)):
        if s[:i] + s[i:] == s[i:][::-1] + s[:i][::-1]:
            intersections.append(i)

    return intersections

