from collections import defaultdict

def optimal_winning_distribution(n, t, prizes, li):
    pr = defaultdict(float)
    possible = [0.] * (n+1)
    for p, l in zip(prizes, li):
        possible[l] += p

    max_val = math.inf
    for i in range(n+1):
        r = sum(possible[j] for j in range(n+1) if j <= i)
        if r < 2 or i == 0:
            continue
        j = t  # Johnny's tickets
        cur_max = float("-inf")
        good_prs = sum(possible[pr[i] - k] for k in range(pr[i]))
        if j > good_prs or (j == good_prs and i > 0):
            if cur_max < max_val:
                max_val = math.ceil(cur_max)
        elif pr[i]:
            cur_max = (r - j) * max_val + max_val
        elif i == 0:
            continue
        else:
            cur_max = max_val
        for j in range(1, min(i+1, r)):
            if cur_max < possible[j] + max_val:
                possible[i] = possible[j]
                cur_max = possible[j] + max_val
            else:
                possible[i] = cur_max
    return max_val
