    count_c, count_p = 0, 0

    for i in range(n):
        if a[i] == 1:
            if count_p > 0:
                max_p = max(max_p, count_c * 2)
                count_p -= 1
        else:
            count_p += 1

        if a[i] == 0:
            if count_c > 0:
                max_c = max(max_c, count_p * 2)
                count_c -= 1
        else:
            count_c += 1

        if count_c * 2 > count_p * 2:
            if count_c > 0:
                min_c = min(min_c, count_c)
            else:
                min_c = max_c

        if count_p * 2 < count_c * 2:
            if count_p > 0:
                min_p = min(min_p, count_p)
            else:
                min_p = max_c

    prefix_sum = [0]
    for i in range(n):
        if a[i] % 2 == 0:
            prefix_sum.append(prefix_sum[-1])
        else:
            prefix_sum[-1] += 1

    results = powerMod(prefix_sum, n - 1 + 2 * max_p + max_c + min_p, MOD)
    result = 0
    for i in range(n + 1):
        result += i * 2 * results[i]
    return result % MOD

