    total_suggestions = 0
    for i, relation in enumerate(friendship_relations):
        for j, friendship in enumerate(relation):
            if friendship == '1':
                adj_matrix[i][j] = 1

    # Calculate the number of suggestions for each user
    suggestions = [0] * n
    for i in range(n):
        for j in range(n):
            if i != j and adj_matrix[i][j] == 0:
                suggestions[i] += 1

    # Calculate the total number of suggestions
    for suggestion in suggestions:
        total_suggestions += suggestion

    return total_suggestions

