import sys

def reverse_substrings(s, t):
    if len(s) != len(t):
        return -1

    k = sys.maxsize
    optimal_positions = []

    for i in range(len(t)):
        index, even = i, True
        while t[index] == s[index % len(s)]:
            if even:
                even = False
                index += 1
            else:
                even = True
                index += 1
        if even and t[index:] == s[index:] and index >= i:
            if len(t) - index < k:
                k = len(t) - index
                optimal_positions = [(index + 1, len(t))]
            elif len(t) - index == k:
                optimal_positions.append((index + 1, len(t)))
        elif not even and index >= i:
            if len(t) - index - 1 < k:
                k = len(t) - index - 1
                optimal_positions = [(i + 2, index)]
            elif len(t) - index - 1 == k:
                optimal_positions.append((i + 2, index))

    if k == sys.maxsize:
        return 0
    return k

