    for i in range(1, kids + 1):
        for j in range(i, kids + 1):
            diff = j - i
            for p in presents[i-1]:
                for q in presents[j-1]:
                    if p != q:
                        graph[p][q] = diff
    return dijkstra(graph, 1)[kinds]

