def is_feasible(n, k, rest_cities, vacations):
    # Initialize the graph and priority queue
    adj = [[] for _ in range(n)]
    rest_indices = set(rest_cities)
    pq = [(0, 0, 0)]  # (time, prev_city, roads_so_far)
    rest_count = [0] * n

    # Build the graph
    for _ in range(n-1):
        x, y = map(int, input().split())
        adj[x-1].append(y-1)
        adj[y-1].append(x-1)

    # Process the rest stops for early exits
    for current in rest_cities:
        if rest_count[current-1] == 0:
            rest_count[current-1] = 1
            pq.append((rest_count[current-1], current-1, 'R'))

    # Initialize timeouts for each vacation plan
    timeouts = {i: 1 << 30 for i in range(len(vacations))}
    pq.extend([(a - 1, b - 1, 0) for a, b in vacations if (a-1 != b-1) for i in range(vacations)])

    # Process vacations with their defined input
    while pq:
        time, last_city, roads = pq.pop()

        # Check timeout for each vacation plan
        string_id = vacations.index((last_city+a[0]-1, a[1]-1))
        if timeouts[string_id] < time:
            timeouts[string_id] = time
            continue

        # Step through each path from the start city's rest index to the end station
        for city in adj[last_city]:
            if city in rest_cities:
                rest_count[city-1] += 1
                pq.append((time + 1, city, 'R'))
            else:
                roads += 1
                if roads <= k:
                    # Step through each path from the last_city to the rest station count of k - 1 <= roads
                    roads -= 1
                    for city_next in adj[city]:
                        if city_next in rest_cities and not rest_count:
                            rest_count[city_next-1] = 1
                            pq.append((time + rest_count[city_next], city_next, 'R'))
                        elif city_next != last_city and city_next != a[0]:
                            pq.append((time + 1, city_next, roads))

    return all(x != 1 << 30 for x in timeouts)
