from math import gcd
from typing import List

def modular_inverse(a: int, mod: int) -> int:
    # Calculate the modular inverse of a under modulo mod
    for i in range(1, mod):
        if (a * i) % mod == 1:
            return i
    return None

def chinese_remainder_theorem(mods: List[int], residues: List[int]) -> int:
    # Apply the generalized Chinese Remainder Theorem to compute the modular inverse product
    product = 1
    for mod, residue in zip(mods, residues):
        product = mod * product
    return (product // gcd(product, product)) % product

@lru_cache(maxsize=None)
def combinations(m: int, n: int) -> int:
    # Precomputed combinations for efficiency
    if n > m: return 0
    if n == 0: return 1
    return m * combinations(m-1, n-1) // n

